    description: json['description'] == null ? null : FormattedText.fromJson(_map(json['description'])),
    media: json['media'] == null ? null : InputPollMedia.fromJson(_map(json['media'])),
    isAnonymous: _bool(json['is_anonymous']),
    allowsMultipleAnswers: _bool(json['allows_multiple_answers']),
    allowsRevoting: _bool(json['allows_revoting']),
    membersOnly: _bool(json['members_only']),
    countryCodes: _list(json['country_codes'], (e) => _string(e)),
    shuffleOptions: _bool(json['shuffle_options']),
    hideResultsUntilCloses: _bool(json['hide_results_until_closes']),
    type: InputPollType.fromJson(_map(json['type'])),
    openPeriod: _int(json['open_period']),
    closeDate: _int(json['close_date']),
    isClosed: _bool(json['is_closed']),
    extra: json['@extra'],
    clientId: json['@client_id'] as int?,
  );

