    bool? isAnonymous,
    bool? allowsMultipleAnswers,
    bool? allowsRevoting,
    bool? membersOnly,
    List<String>? countryCodes,
    bool? shuffleOptions,
    bool? hideResultsUntilCloses,
    InputPollType? type,
    int? openPeriod,
    int? closeDate,
    bool? isClosed,
    dynamic extra,
    int? clientId,
  }) => InputMessagePoll(
